insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-boker$q$,$q$שיר בוקר טוב$q$,$q$<p>מתחילים תמיד בשיר בוקר טוב. הוא נמצא בפלייליסט שלנו:</p><p>🎵 <a href="https://open.spotify.com/playlist/5761yc5agCIByoKWmrwxVq?si=ZR_Neis0QFmPzS8bHa9qSQ&amp;pi=PPKZnrAqSPy8P" target="_blank" rel="noopener">הפלייליסט של מימו</a>, כולל שיר הבוקר טוב שלנו 🤍</p>$q$,null,null,null,null,array[$q$calm$q$]::text[],'{}'::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
