insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-hakpatzot$q$,$q$הקפצות אגן$q$,null,null,null,$q$אופ אופ אופ<br>אופ אופ אופ<br>נעלה למעלה<br>ונרד למטה<br>נקפוץ$q$,$q$https://pkekucngirkjqigpmlrt.supabase.co/storage/v1/object/public/videos/warmup/03-hakpatzot-agan.mp4$q$,array[$q$balance$q$]::text[],'{}'::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-sivuvim$q$,$q$סיבובי אגן$q$,$q$<p>ואז צד שני.</p>$q$,null,null,$q$עוגה עוגה עוגה במעגל נחוגה<br>נסתובבה כל היום עד אשר נמצא מקום<br>קדימה אחורה, קדימה אחורה<br>קדימה ואחורה$q$,$q$https://pkekucngirkjqigpmlrt.supabase.co/storage/v1/object/public/videos/warmup/04-sivuvei-agan.mp4$q$,array[$q$balance$q$]::text[],'{}'::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-kapot$q$,$q$טפיחות כפות ידיים וכפות רגליים$q$,$q$<p>טפיחות על הרצפה וסגירה לחיבוק, עבודה על סימטריה.</p>$q$,null,null,null,$q$https://pkekucngirkjqigpmlrt.supabase.co/storage/v1/object/public/videos/warmup/05-kapot-a.mp4$q$,array[$q$hands$q$,$q$senses$q$]::text[],array[$q$סימטריה$q$]::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-kapot-b$q$,$q$טפיחות כפות ידיים וכפות רגליים, זווית נוספת$q$,$q$<p>אותו תרגיל, מקרוב: טפיחות על הרצפה וסגירה לחיבוק, עבודה על סימטריה.</p>$q$,null,null,null,$q$https://pkekucngirkjqigpmlrt.supabase.co/storage/v1/object/public/videos/warmup/05-kapot-b.mp4$q$,array[$q$hands$q$,$q$senses$q$]::text[],array[$q$סימטריה$q$]::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-alachsonim$q$,$q$אלכסונים$q$,$q$<p>לשני הצדדים!</p>$q$,null,null,$q$יד ורגל נקרב ונרחיק, נקרב<br>יד ורגל נקרב ונרחיק$q$,$q$https://pkekucngirkjqigpmlrt.supabase.co/storage/v1/object/public/videos/warmup/06-alachsonim.mp4$q$,array[$q$side$q$]::text[],array[$q$קו אמצע$q$]::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-macha$q$,$q$מחא מחא$q$,null,null,null,$q$מחא מחא כפיים,<br>ניסע לירושלים<br>אחת, שתיים, שלוש<br>ידיים על הראש!$q$,null,array[$q$hands$q$]::text[],array[$q$קו אמצע$q$]::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-nadneda$q$,$q$נדנדה$q$,$q$<p>אוחזים את הידיים והרגליים ומנדנדים מצד לצד, כשהלחי נוגעת ברצפה.</p>$q$,null,null,$q$נד נד נד נד<br>רד עלה עלה ורד<br>נד נד נד נד<br>רד עלה עלה ורד$q$,$q$https://pkekucngirkjqigpmlrt.supabase.co/storage/v1/object/public/videos/warmup/07-nadneda.mp4$q$,array[$q$side$q$,$q$balance$q$]::text[],'{}'::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-batzek$q$,$q$ללוש את הבצק$q$,$q$<p>נוסף אחרי מפגש 2.</p><p>לסובב לשכיבה על הצד דרך הרגל, לדאוג שהטוסיק בסוג של ערסול, ו״לעסות״ את התינוק, וזה גם זמן בטן.</p>$q$,null,null,$q$ללוש ללוש את הבצק<br>ללוש ללוש את הבצק<br>ללוש ללוש את הבצק<br>נעשה ממנו פיצה$q$,null,array[$q$side$q$,$q$tummy$q$]::text[],'{}'::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wu-batzek-2$q$,$q$ללוש את הבצק, צד שני$q$,$q$<p>אותו דבר לצד השני, ושוב זמן בטן.</p>$q$,null,null,null,null,array[$q$side$q$,$q$tummy$q$]::text[],'{}'::text[],null,true) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$itzuf$q$,$q$עיטוף$q$,$q$<p>על הגב בלבד, בד דק, לא מהודק, רגליים חופשיות ומפושקות. עד גיל חודשיים, לפני ההתהפכות.</p>$q$,$q$הידיים חוזרות לאמצע והגוף מרגיש מוחזק, ואז רפלקס מורו (רפלקס הבהלה: פשיטת ידיים פתאומית, נעלם סביב 4 עד 5 חודשים) מפסיק להפריע. תינוק רגוע פנוי ללמידה.$q$,null,null,null,array[$q$calm$q$]::text[],array[$q$מורו$q$]::text[],$q$עד חודשיים$q$,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$lift-lower$q$,$q$הרמה והורדה$q$,$q$<p>אומרים לו קודם, מרימים מהגו ולא מהגפיים, תמיד דרך הצד עם תמיכה בראש. מורידים לאט.</p>$q$,$q$הרמה פתאומית היא בשבילו נפילה. הרמה מוכנה ואיטית היא הודעה שהוא בטוח, וגם שיעור ראשון בסיבוב מסודר של הגוף.$q$,null,null,null,array[$q$carry$q$]::text[],array[$q$הנדלינג$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$side-lying$q$,$q$שכיבה על הצד$q$,$q$<p>עם אביזר שתומך בגב, או שאת שוכבת מולו ותומכת ביד. שוהים, לא רק עוברים.</p>$q$,$q$הצד מכיר לו את גבולות הגוף, מביא ידיים ורגליים לאמצע ולפה, ויוצר סימטריה. בלי צד אין התהפכות מסודרת.$q$,null,null,null,array[$q$side$q$]::text[],array[$q$סימטריה$q$,$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$cradle$q$,$q$ערסול$q$,$q$<p>ראש בכיפוף המרפק, גוף לאורך האמה, היד השנייה אוספת טוסיק ורגליים. גב מעוגל, ברכיים גבוהות מהטוסיק. ראש ורגליים באותו קו: <em>ערסול זה כמו חיוך</em>.</p>$q$,$q$מוציא את מורו מהמערכת, מאפשר קשר עין, מקל על גזים, עוזר לו לסנן גירויים, ומפעיל את החישה העמוקה (התחושה שהגוף נותן לעצמו: איפה הידיים שלי, בלי להסתכל). שומר על הכפיפה הפיזיולוגית, המנח המכונס שהכיר ברחם. וכל זה ממקום של מנוחה.$q$,$q$דונה, טרמפולינה וסלקל הם <strong>לא</strong> מנח ערסול.$q$,null,null,array[$q$calm$q$,$q$carry$q$]::text[],array[$q$מורו$q$,$q$פרופריוצפטיבית$q$,$q$כפיפה פיזיולוגית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$matok$q$,$q$מתו״ק: מגע, תנועה וקול$q$,$q$<p>תנועה מהברכיים. מגע יציב בקצב הדופק שלך. קול: ״אההה״ ו״בה בה״, לא רק ״שששש״.</p>$q$,$q$זה בדיוק מה שהוא שמע בתוכך. ההבדל בין ״שששש״ ל״אההה״ הוא הוויברציה: ״אההה״ עובר דרך הגוף שלך אליו, ובהמשך הוא יחקה אותו. ומגע הוא לא פינוק, הוא צורך בסיסי.$q$,null,null,null,array[$q$calm$q$,$q$hands$q$]::text[],array[$q$מתו״ק$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$relax-pouf$q$,$q$הרפיה: פוף וריכוז צלילים$q$,$q$<p>פוף וריכוז צלילים. בעמידה, ערסול עם מוזיקה.</p>$q$,$q$סיום קבוע מלמד את מערכת העצבים לרדת בהדרגה ולא בבת אחת. זה הכלי שאת לוקחת הביתה לפני שינה.$q$,null,null,null,array[$q$calm$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$communication$q$,$q$תקשורת מהיום הראשון$q$,$q$<ul><li>תינוקות נולדים עם יכולת תקשורתית <strong>מהיום הראשון</strong>: דרך בכי, מבט, צלילים, חיקוי, הפניית קשב, ותנועות ידיים ורגליים.</li><li><strong>בכי הוא תקין, ואנחנו רוצות לשמוע אותו.</strong> דרך הבכי והתקשורת אנחנו יכולות לתת לו את המענה ואת הוויסות שהוא צריך (ויסות בשניים).</li><li>לתת לו לענות ולהיות פעיל באינטראקציה: <strong>serve and return</strong>.</li><li><strong>ג׳סטות</strong>: תנועה שמתלווה למילה. כל ג׳סטה היא מילה לכל דבר.</li><li>תקשורת טובה משחררת אוקסיטוצין, ומחזירה אותנו לסנכרון ההורמונלי.</li><li><strong>דיבור אימהי</strong> מתאפיין באינטונציה מוגזמת, מבעים פשוטים וקצרים, חזרות רבות, טון דיבור גבוה והפסקות מרובות. ההבדל בינו לבין ״דיבור תינוקי״: דיבור תינוקי הוא מהיר, רק אמא מדברת, ואין בו תקשורת.</li></ul>$q$,null,null,null,null,array[$q$hands$q$]::text[],array[$q$ויסות בשניים$q$,$q$serve and return$q$,$q$דיבור אימהי$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$why-tummy$q$,$q$למה זמן בטן$q$,$q$<p>מנח בטן הוא <strong>הבסיס לכל שלבי ההתפתחות הבאים</strong>, ולכן חשוב שהמנח יהיה מאורגן ויעיל. כדי לשפר שכיבה על הבטן מתחילים דווקא כשהם על הגב, תוך שחרור מתח בחימום.</p>$q$,null,null,null,null,array[$q$tummy$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$why-side$q$,$q$למה כל כך חשוב להיות על הצד$q$,$q$<ol><li>שלב מקדים והכרחי ללמידה לפני ההתהפכות</li><li>הכרת גבולות הגוף</li><li>הכרת צידי הגוף ואיברי הגוף</li><li>גירוי במערכת החישה</li><li>יצירת סימטריה, הבאת ידיים ורגליים לקו האמצע והכנסתן לפה</li></ol>$q$,null,null,null,null,array[$q$side$q$]::text[],array[$q$סימטריה$q$,$q$קו אמצע$q$,$q$פרופריוצפטיבית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$roll-dough$q$,$q$גלגול מהגב לבטן$q$,$q$<p>גלגול מהגב לבטן עם ״ללוש את הבצק״ לשני הצדדים, ובריכת דגים.</p><p><strong>חשוב:</strong> איך משחררים יד שנשארת כלואה.</p>$q$,null,null,null,null,array[$q$side$q$,$q$tummy$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$tummy-mirror$q$,$q$זמן בטן עם מראה$q$,$q$<p>לעודד הרמת ראש ושהייה על המרפקים.</p>$q$,$q$לחיזוק חגורת הכתפיים ושרירי הצוואר.$q$,null,null,null,array[$q$tummy$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$tummy-off-mat$q$,$q$זמן בטן, לא רק על המשטח$q$,$q$<ol><li>נשענות על פוף, התינוק על בית החזה שלנו, פנים מול פנים</li><li>על הירכיים שלנו עם הפנים החוצה: תינוק מול תינוק, או אמא עוברת עם רעשן</li><li>על השוקיים שלנו, להרים ולהוריד, פנים מול פנים</li><li>בעמידה, אמא מול אמא או מול מראה. הטוסיק נשען על הבטן של אמא, אמא מחזיקה בבית החזה ומשעינה את היד קדימה, כשהבטן של התינוק על היד. השכמות מתרחקות ונוצרת הזדקפות והרמת ראש.</li></ol>$q$,null,null,null,null,array[$q$tummy$q$,$q$carry$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$luna-park$q$,$q$לונה פארק: מעבר בין מנחים$q$,$q$<p>מתו״ק עם שיר, תוך כדי הסבר וחזרה לחשיבות. שימו מוזיקה כיפית וקצבית, שיהיה לכן רצון לזוז.</p><ol><li>כתף</li><li>כתף שנייה</li><li>ערסול קדמי, נכנסות פנימה למעגל ונפגשות עם הרגליים</li><li>נמר על העץ, נדנודים מצד לצד ולאמצע</li><li>ערסול רגיל, ואז עוברות לצד השני</li></ol>$q$,null,null,null,null,array[$q$carry$q$,$q$balance$q$]::text[],array[$q$מתו״ק$q$,$q$הנדלינג$q$,$q$וסטיבולרית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$belly-on-belly$q$,$q$בטן על בטן$q$,$q$<p>נשכבות על הגב כשהבייבי על הבטן שלנו, ומתנדנדות יחד מצד לצד.</p>$q$,$q$מחזק את מערכת שיווי המשקל תוך תחושת ביטחון וקרבה.$q$,null,null,null,array[$q$balance$q$,$q$tummy$q$,$q$calm$q$]::text[],array[$q$וסטיבולרית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$physio-ball$q$,$q$כדור פיזיו$q$,$q$<ul><li><strong>על הבטן:</strong> קפיצות קטנות, תנועה מצד לצד וקדימה ואחורה.<br><em>המטרה:</em> לעודד שיווי משקל תוך התנגדות לכוח הכבידה.</li><li><strong>על הגב:</strong> ראש ושכמות על הכדור, מחזיקות בעדינות מהאגן ומהירכיים, מרחיקות את הכדור ומקרבות.<br><em>המטרה:</em> לעבוד על כפיפה וזקיפה של הגב, ולעודד חיזוק שרירי הליבה וזוקפי הגב. טוב גם לשיפור זמן בטן.</li></ul>$q$,null,null,null,null,array[$q$balance$q$,$q$tummy$q$]::text[],array[$q$וסטיבולרית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$balance-pouf$q$,$q$שיווי משקל עם הפוף$q$,$q$<p>שהייה לצדדים ונדנוד, ותנועה במרחב.</p>$q$,null,null,null,null,array[$q$balance$q$]::text[],array[$q$וסטיבולרית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$relax-tetra$q$,$q$הרפיה: נדנוד בטטרה$q$,$q$<p>נדנוד בטטרה, ואז פוף וריכוז צלילים.</p>$q$,null,null,null,null,array[$q$calm$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$vision$q$,$q$מיקוד מבט: מה הוא באמת רואה$q$,$q$<p>תינוקות מעדיפים <strong>פנים אנושיות</strong>. בהתחלה הם רואים מרחק של כ־20 ס״מ, רואים צללים ומטושטש, ויש להם יכולת למקד מבט בגירוי מסוים, או להפנות את המבט והקשב כשמשהו מפריע להם או לא מעניין אותם.</p>$q$,null,null,null,null,array[$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$midline-gaze$q$,$q$הבאת ידיים לקו האמצע ומיקוד מבט$q$,$q$<ul><li>אמא מתקרבת לפנים של התינוק, והתינוק מלטף את הפנים של אמא</li><li>אמא יושבת מול הפוף, מביאה אביזר מול הפנים ומביאה את הידיים לקו האמצע</li><li>מיקוד מבט: אמא מול תינוק, וזזה מצד לצד</li></ul>$q$,null,null,null,null,array[$q$hands$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$head-rest$q$,$q$הנחת ראש$q$,$q$<ul><li><strong>על המשטח:</strong> לכופף רגל אחת הצידה, כשהיד הנגדית ישרה לצד הגוף, להרים קצת את האגן ולעשות ניעות קדימה ואחורה</li><li><strong>על אמא:</strong> להביא אותו קדימה לישיבה על האמה, כיפוף ברכיים של אמא והישענות קדימה, עד שהתינוק מניח את הראש</li><li><strong>על הכדור</strong></li></ul>$q$,$q$וכמה חשוב לדעת גם <strong>להרפות</strong>, ולא רק להחזיק את הראש עם כל המשקל שלו.$q$,null,null,null,array[$q$calm$q$,$q$balance$q$]::text[],array[$q$טונוס$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$extra-handling$q$,$q$אקסטרה: הנדלינג ומעבר בין מנחים$q$,$q$<p>הנדלינג, מעבר בין מנחים, וזמן בטן על הרגליים כשאמא עוברת עם אביזר או מול מראה.</p>$q$,null,null,null,null,array[$q$carry$q$,$q$tummy$q$]::text[],array[$q$הנדלינג$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$relax-on-mom$q$,$q$הרפיה על אמא$q$,$q$<p>הרפיה על אמא, עם שיר מרגש.</p>$q$,null,null,null,null,array[$q$calm$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$textures$q$,$q$חשיפה למרקמים$q$,$q$<p>נחשפנו למרקמים שונים דרך לוחות חושים ואביזרים, והיה רגע קסום של תקשורת ושיח גם בלי מילים, בין כל אמא ותינוק.</p><ul><li>החשיפה היא <strong>הדרגתית ומותאמת לטמפרמנט</strong> של כל תינוק. להיות קשובות לבייבי ולסימנים שלו.</li><li>לא צריך כדורי קוצים כל הזמן.</li><li>כמה שאפשר, לאפשר לתינוקות להיות יותר חשופים, בעיקר בכפות הידיים וכפות הרגליים.</li></ul><p><strong>איך תרגלנו:</strong></p><ul><li>בזמן בטן: משטח חושי עם מרקמים שונים</li><li>בשכיבה על הגב: אביזרי חישה: ספוג, מברשת, נוצה, כדור קוצים, מטפחת, פונפונים</li></ul>$q$,null,null,null,null,array[$q$senses$q$,$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$carrier$q$,$q$מנשא$q$,$q$<p>ראינו איך להשתמש במנשא בד גם במנח רגיל וגם במנח ערסול.</p><ul><li><strong>מנשא בד הוא המומלץ ביותר</strong>, אבל אם התינוק ממש קטן, לא לשים אותו בערסול. בסוף, הכי חשוב מה שנוח לאמא.</li><li>מנח ערסול דורש דיוק והרבה תשומת לב לבטיחות, עד כדי כך שיש מקצוע שנקרא יועצת מנשאים.</li></ul>$q$,null,$q$<strong>כשמשתמשים במנשא, במיוחד במנח ערסול, תמיד לוודא:</strong><ul><li>נתיב האוויר פתוח</li><li>הפנים של הבייבי גלויות ולא מכוסות</li><li>הסנטר לא צמוד לבית החזה. מרווח של שתי אצבעות בין הסנטר לחזה</li><li>הבייבי לא מעורסל עמוק מדי או סגור מדי</li><li>השהייה במנח הזה היא לפרקי זמן קצרים, בדומה לשימוש בסלקל</li><li>משתמשים במנשא לפי הוראות היצרן</li><li>פנים החוצה רק אחרי גיל 4 חודשים</li><li>אם יש ספק, מתייעצות עם יועצת מנשאים</li></ul>$q$,null,null,array[$q$carry$q$]::text[],array[$q$דיספלזיה$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$m5-extras$q$,$q$עוד נגענו במפגש$q$,$q$<ul><li>הקלה על גזים</li><li>רפלקס האחיזה, פתיחת ידיים וקו האמצע</li><li>זמן סיום ופרידה</li></ul>$q$,null,null,null,null,array[$q$hands$q$,$q$calm$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$relax-glove$q$,$q$הרפיה: פוף וריכוז צלילים עם כפפה$q$,$q$<p>פוף וריכוז צלילים עם כפפה.</p>$q$,null,null,null,null,array[$q$calm$q$,$q$senses$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$mg-attachment$q$,$q$מאפייני ההתקשרות בגיל הזה$q$,$q$<ul><li>התינוק מבחין בין אמא לבין אדם זר שהוא לא מכיר.</li><li>הוא נרגע מהר יותר אצל הדמות המטפלת העיקרית.</li></ul>$q$,null,null,null,null,array[$q$hands$q$,$q$calm$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$mg-midline-theory$q$,$q$חציית קו האמצע ומערכת ההצלבה, וזה קריטי$q$,$q$<p>אם תינוק לא יודע לחצות את מרכז הגוף שלו, הדרך היחידה שלו להתהפך היא לזרוק את כל הגוף בבת אחת כמו בלוק נוקשה, תוך הקשתת הגב ומתח בצוואר.</p><p>כשהוא לומד להביא קודם כל יד אחת או רגל אחת לצד השני, הגוף מסתובב מעצמו בספירלה רכה, תוך הפעלת שרירי הבטן ותוך תחושת ביטחון ושליטה.</p><p>ההתפתחות מגיעה מהבאת היד או הרגל למרכז, ולא מהצוואר. וכשאנחנו מעודדות תנועות אלכסוניות, אנחנו לא רק מחזקות את הגוף. אנחנו גם <strong>מייצרות קשרים מוחיים</strong>. זה הבסיס להתפתחות ולזחילה.</p>$q$,null,null,null,null,array[$q$side$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$mg-back-to-tummy$q$,$q$מעבר מהגב לבטן$q$,$q$<p>כשהתינוק על הגב, מעבירים רגל ב־90 מעלות לכיוון הצד הנגדי, ואוחזים בעדינות בטוסיק כדי שלא יתהפך בחזרה. תוך כדי מגרים עם צעצוע בקו העיניים. המטרה שיושיט יד לעבר הצעצוע, יחצה את קו האמצע, ואז מובילים את ההתהפכות.</p>$q$,null,null,null,null,array[$q$side$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$judo-flip$q$,$q$היפוך ג׳ודו$q$,$q$<p>הנחת לחי וכתף על המשטח, כדי לעזור לבייבי לעבור מהבטן לגב.</p>$q$,null,null,null,null,array[$q$side$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$mg-midline-on-back$q$,$q$חציית קו האמצע כשהתינוק על הגב$q$,$q$<ol><li>אמא מגרה את אמצע הגוף עם כדור ומרימה אותו כדי שהתינוק יגיע למרכז הגוף. אחרי שהצליח, לעבור לחציית קו האמצע.</li><li>עם מדבקה על האף של אמא, תוך כדי החזקה של יד אחת של התינוק.</li><li>עם אטבים על הבגד של התינוק.</li></ol>$q$,null,null,null,null,array[$q$side$q$,$q$hands$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$mg-midline-on-tummy$q$,$q$חציית קו האמצע כשהתינוק על הבטן$q$,$q$<ol><li>אמא מול תינוק, מביאה לו משהו ליד ומגרה אותו להגיע למרכז הגוף.</li><li>אמא מול תינוק, מגרה עם צעצוע תוך כדי שהיא מנטרלת יד אחת, לסירוגין. המטרה: לחצות את קו האמצע באלכסון.</li></ol>$q$,null,null,null,null,array[$q$tummy$q$,$q$side$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$relax-sounds$q$,$q$הרפיה: ריכוז צלילים$q$,$q$<p>ריכוז צלילים.</p>$q$,null,null,null,null,array[$q$calm$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$feet-flex$q$,$q$כפיפה ויישור רגליים בשלושה מנחים$q$,$q$<p>לכיוון הבטן, באלכסון וביישור, עם השיר ״מאחורי ההר״ (שלושת הגמדים).</p>$q$,null,null,null,null,array[$q$balance$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$feet-massage$q$,$q$עיסוי כפות הרגליים וחקר מרקמים$q$,$q$<p>עיסוי כפות הרגליים וחקר מרקמים.</p>$q$,null,null,null,null,array[$q$senses$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$artificial-floor$q$,$q$רצפה מלאכותית$q$,$q$<p>כשהתינוק שוכב על הגב, אמא מצמידה את כפות הרגליים שלו למשטח קשיח וישר (כמו ספר או לוח חלק), ויוצרת צעדים מהעקב עד לאצבעות.</p>$q$,null,null,null,null,array[$q$balance$q$,$q$senses$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$feet-to-face$q$,$q$הבאת רגליים לפנים$q$,$q$<p>להביא בעדינות את כפות הרגליים אל הפנים, הפה והלחיים.</p>$q$,$q$כדי להגביר מודעות לאיברי הגוף ולחזק את שרירי הבטן.$q$,null,null,null,array[$q$side$q$,$q$senses$q$]::text[],array[$q$פרופריוצפטיבית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$scarves-feet$q$,$q$קשירת מטפחות לכפות הרגליים$q$,$q$<p>קשירת מטפחות לכפות הרגליים, כדי לעורר סקרנות ולעודד אותו למשוך אותן.</p>$q$,null,null,null,null,array[$q$senses$q$,$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$peekaboo$q$,$q$משחקי קוקו עם מטפחת$q$,$q$<p>חשוב לשחק בקצב איטי, לאפשר לבייבי זמן לעבד, וליצור הפסקות בין הכיסוי לחשיפה. כדאי להתבונן בתגובות שלו ולהתאים את הקצב אליו.</p>$q$,$q$תומכים בהבנה ההדרגתית שגם כשאמא או חפץ נעלמים לרגע משדה הראייה, הם עדיין קיימים וחוזרים.$q$,null,null,null,array[$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$front-cradle-frog$q$,$q$ערסול קדמי עם תמיכה$q$,$q$<p>אחיזה במנח ערסול קדמי מעוגל, והבאת כפות הרגליים למגע עם הרצפה בתנוחת צפרדע, עם השיר ״צפרדע קווה קווה קווה, צפרדע ירוקה״.</p>$q$,null,null,null,null,array[$q$carry$q$,$q$balance$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$wall-push$q$,$q$דחיפת קיר מערסול קדמי$q$,$q$<p>מאותו מנח, מקרבים את התינוק אל הקיר ומאפשרים לו להצמיד את כפות הרגליים ולדחוף ממנו.</p>$q$,null,null,null,null,array[$q$carry$q$,$q$balance$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$mothers-circle$q$,$q$מעגל אמהות$q$,$q$<p>התינוקות מוחזקים בערסול קדמי, האמהות הולכות אחת אחרי השנייה ולפי המוזיקה עוצרות, ואז הרגליים של התינוק דוחפות את הגב של האמא שלפניה.</p>$q$,null,null,null,null,array[$q$carry$q$,$q$balance$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$twist$q$,$q$תרגיל פיתול$q$,$q$<p>מלמד את התינוק לייצר הפרדת תנועה בין פלג גוף עליון לתחתון, לפתוח את בית החזה ולסגור חזרה לקו האמצע כשהוא על הצד.</p>$q$,$q$זה הבסיס להתהפכות.$q$,null,null,null,array[$q$side$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$tummy-elbow$q$,$q$זמן בטן עם ניתוק מרפק$q$,$q$<p>כשהבייבי על הבטן, אמא מחזיקה בעדינות מהכתפיים ומניעה מצד לצד. השאיפה היא לראות שהמרפק בצד הנגדי מתנתק מהמזרן, ושברגל הנגדית נוצרת רוטציה ודחיפה.</p>$q$,$q$תנועה קריטית שבונה את התשתית לזחילה העתידית.$q$,null,null,null,array[$q$tummy$q$,$q$side$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$cheek-to-cheek$q$,$q$לחי אל לחי (היפוך מהבטן לגב)$q$,$q$<p>אמא מחזיקה את התינוק קרוב אליה, לחי אל לחי, ומוציאה אותו בעדינות מאיזון כדי להבחין איך הגוף שלו מגיב, מתארגן ומשלים את ההיפוך.</p>$q$,null,null,null,null,array[$q$side$q$,$q$balance$q$]::text[],array[$q$וסטיבולרית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$tetra-balance$q$,$q$אתגר שיווי המשקל על טטרה$q$,$q$<p>מניחים את התינוקות על הבטן על טטרה גדולה ומניעים אותה בעדינות בשמיניות, כדי לעורר העברות משקל רכות ויזומות.</p>$q$,null,null,null,null,array[$q$balance$q$,$q$tummy$q$]::text[],array[$q$וסטיבולרית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$tetra-trick$q$,$q$טריק חיתול הטטרה (היפוך מונחה)$q$,$q$<p>משכיבים את התינוק על חיתול טטרה גדול, כשרגליו מחוץ לחיתול. אמא מרימה לאט את קצה החיתול לכיוונה כדי להוציא אותו משיווי משקל ולייצר מעין ״קיר״. <strong>תנועת ההיפוך צריכה לנבוע מהתינוק עצמו</strong>, כשהוא מתגלגל לאט ובשליטה.</p>$q$,null,null,null,null,array[$q$side$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$big-clock$q$,$q$משחק השעון הגדול$q$,$q$<p>עם השיר של השעון (״ביום וגם בלילה דופק…״), האמהות יושבות במעגל ומניעות את התינוקות מהרגליים, היפוך אחר היפוך סביבן, בצורה זורמת.</p>$q$,null,null,null,null,array[$q$side$q$,$q$balance$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$relax-hotdog$q$,$q$הרפיה: הוט דוג על הפוף$q$,$q$<p>מניחים את התינוקות על הפוף ומניעים אותו מצד לצד כמו ״הוט דוג״, כדי להרגיע את מערכת העצבים.</p>$q$,null,null,null,null,array[$q$calm$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$hands-massage$q$,$q$עיסוי כפות ידיים וחקר חושי$q$,$q$<p>בעזרת אביזרים: כדור קוצים, ספוג ומרקמים שונים, כדי להגביר את המודעות לידיים.</p>$q$,null,null,null,null,array[$q$senses$q$,$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$artificial-wall$q$,$q$קיר מלאכותי$q$,$q$<p>דחיסת כפות הידיים בעזרת משטח ישר וקשיח כמו ספר.</p>$q$,null,null,null,null,array[$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$hip-to-mat$q$,$q$מעבר למזרן מהמותן של אמא$q$,$q$<p>אמא נשכבת על הצד על המזרן, מניחה את הבייבי על המותן שלה ומטה את הגוף בעדינות לכיוון הרצפה, במטרה לראות את הידיים של התינוק נשלחות ומגיעות אל המזרן.</p><p><em>זה הזמן להכין את המצלמה, יוצאים מזה סרטונים מעולים.</em></p>$q$,null,null,null,null,array[$q$balance$q$,$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$arms-on-mom$q$,$q$יישור ידיים על אמא$q$,$q$<p>אמא שוכבת על הרצפה, הבייבי עליה, והוא מיישר ידיים ומניח אותן על בית החזה שלה (מנח ״מטוס״).</p>$q$,null,null,null,null,array[$q$hands$q$,$q$tummy$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$press-palms$q$,$q$לחיצה על כפות הידיים$q$,$q$<p>כשהבייבי על הבטן, אמא מניחה ידיים על כפות הידיים שלו ונותנת לחיצה קלה והתנגדות מבוקרת.</p>$q$,$q$ההתנגדות גורמת למוח להגיב וליישר את המרפקים קדימה. (אם בהתחלה קשה להם, נראה שהם מנסים לפצות דרך תנועת הרגליים.)$q$,null,null,null,array[$q$hands$q$,$q$tummy$q$]::text[],array[$q$פרופריוצפטיבית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$weight-legs$q$,$q$העברת משקל דרך הרגליים$q$,$q$<p>התינוק על הבטן, מכופפות את הברך לכיוון בית השחי או בית החזה, התינוק מעביר משקל לצד הנגדי, המרפק והכתף נשענים על המשטח, והוא משלים את ההיפוך בעצמו.</p>$q$,$q$הרגליים הן המנוע וההגה של הגוף. ברגע שמניעים את הרגליים, זה משפיע אוטומטית על מנח הגב, נוצרת העברת משקל בפלג הגוף העליון, והראש משלים את התנועה.$q$,null,null,null,array[$q$side$q$,$q$balance$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$lioness$q$,$q$תרגיל היפוך לביאה וגורה$q$,$q$<p>לשני הצדדים.</p>$q$,null,null,null,null,array[$q$side$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$fall-sim$q$,$q$סימולציית נפילה כלפי מטה (רפלקס הבלימה)$q$,$q$<p>אמא אוחזת בתינוק מהצלעות כשהוא פונה קדימה, ומטה אותו בעדינות ובקצב מבוקר לעבר הפוף, כדי לראות איך הוא מגיב ופותח ידיים קדימה כדי לבלום.</p>$q$,null,null,null,null,array[$q$balance$q$]::text[],array[$q$מורו$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$airplane$q$,$q$תרגיל המטוס (רפלקס שיווי משקל הגנתי)$q$,$q$<p>מרימים את התינוק מעל הראש, כשאמא אוחזת היטב מאזור הצלעות ובית השחי, ומדמים טיסה, כדי להפעיל את השרירים הזוקפים.</p>$q$,null,null,null,null,array[$q$balance$q$,$q$carry$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$ball-weight-shift$q$,$q$העברת משקל על כדור פיזיו$q$,$q$<p>התינוק על הבטן על הכדור. אמא תומכת ואוחזת בצד אחד (חוסמת את הזרוע והיד שנשארות על הכדור) ומניעה את הכדור לכיוון הצד החסום. ביד השנייה החופשית היא נותנת גירוי ויזואלי או משחק במרכז, ומעודדת אותו לתפוס ולחזור לקו האמצע.</p>$q$,null,null,null,null,array[$q$tummy$q$,$q$balance$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$braking$q$,$q$תרגיל פעולת הבלימה$q$,$q$<p>(כדור פיזיו, גליל או הרגל של אמא): התינוק על הבטן מעל האביזר, אמא תומכת בעדינות באגן ומניעה אותו קצת קדימה. כשהוא נוטה לרצפה, הרפלקס הטבעי יהיה להושיט כפות ידיים ולבלום. כשהידיים פרושות על המשטח, ניעות קטנות קדימה ואחורה, כמו רוקינג.</p>$q$,$q$האביזר מוריד משקל מהגוף ומקל עליו לתרגל יישור מרפקים בלי לשאת את כל משקלו.$q$,null,null,null,array[$q$tummy$q$,$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$bubbles$q$,$q$תפיסת בועות סבון בגובה העיניים$q$,$q$<p>כשהבייבי על האביזר, מפריחים בועות לא בגובה הרצפה אלא בגובה העיניים שלו או מעט גבוה יותר.</p>$q$,$q$כדי לעקוב ולנסות לתפוס, הוא מפעיל את השרירים הזוקפים ודוחף אוטומטית את המזרן בכפות הידיים כדי להרים את החזה גבוה. <em>אם הגירוי למטה, הוא יישאר על האמות. אם הגירוי עולה, הגוף מחפש דחיפה אנכית.</em>$q$,null,null,null,array[$q$tummy$q$,$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$pouf-ride$q$,$q$הנעה על פוף על הבטן$q$,$q$<p>מסיעים את הפוף קדימה ואחורה בחלל, לשיפור תפיסת המרחב.</p>$q$,null,null,null,null,array[$q$balance$q$,$q$tummy$q$]::text[],array[$q$וסטיבולרית$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$comm-circle$q$,$q$מעגל תקשורת$q$,$q$<p>מעגל תקשורת.</p>$q$,null,null,null,null,array[$q$hands$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$textures-part$q$,$q$חלק מרקמים$q$,$q$<p>חשיפה וחקירה של מרקמים שונים על כפות הידיים, הרגליים והעור כולו.</p>$q$,$q$העור הוא האיבר הגדול בגוף, ומגע הוא תקשורת לא־מילולית מעולה.$q$,null,null,null,array[$q$senses$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$peekaboo-tickles$q$,$q$משחקי קוקו ודגדוגים$q$,$q$<p>תקשורת ופיתוח קוגניטיבי. ומכיוון שמתקרבים לשלב הטעימות, מנצלות את ההזדמנות לתת גירויים תחושתיים עדינים בעזרת הידיים או המרקמים סביב אזור הפה, הלחיים והשפתיים.</p>$q$,null,null,null,null,array[$q$hands$q$,$q$senses$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$recap$q$,$q$וגם: חיבור של הכל$q$,$q$<p>במפגש האחרון חיברנו את כל אבני הדרך של חמשת השבועות:</p><ul><li>ניתוק מרפק, הושטת יד וחציית קו אמצע: עם בועות סבון, כדור פיזיו והעברת משקל, ומשחקים שנדבקים לחלון</li><li><strong>לונה פארק:</strong> מכתף לכתף, לערסול קדמי, לנמר על העץ ולערסול רגיל, ואז לצד השני</li><li>תנועה במרחב על פוף, כשהתינוק על הבטן</li><li>תינוק על הגב וכפות הרגליים על הרצפה, לראות איך הוא משתמש בהתנגדות של הרצפה כדי לנוע לאחור</li><li>שיר ״לעוףףף״</li></ul>$q$,null,null,null,null,array[$q$side$q$,$q$carry$q$,$q$balance$q$]::text[],array[$q$קו אמצע$q$]::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into exercises (slug,title,how,why,caution,lyrics,video_url,topics,terms,age_range,is_warmup) values ($q$relax-ball$q$,$q$הרפיה על כדור פיזיו$q$,$q$<p>משכיבים את התינוקות על הצד ומניעים בעדינות, כדי לעזור להם להרפות וללמוד להניח את הראש בנינוחות. ואז ריכוז צלילים.</p>$q$,null,null,null,null,array[$q$calm$q$]::text[],'{}'::text[],null,false) on conflict (slug) do update set title=excluded.title, how=excluded.how, why=excluded.why, caution=excluded.caution, lyrics=excluded.lyrics, video_url=excluded.video_url, topics=excluded.topics, terms=excluded.terms, age_range=excluded.age_range, is_warmup=excluded.is_warmup;
insert into glossary (term,plain,aliases) values ($q$מורו$q$,$q$רפלקס הבהלה: פשיטת ידיים פתאומית כשהתינוק מרגיש שהוא נופל או נבהל. נעלם סביב גיל 4 עד 5 חודשים. עיטוף וערסול מרגיעים אותו.$q$,array[$q$רפלקס מורו$q$,$q$רפלקס המורו$q$,$q$רפלקס הבהלה$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$פרופריוצפטיבית$q$,$q$החישה העמוקה: התחושה שהגוף נותן לעצמו. איפה הידיים שלי, בלי להסתכל. מגע יציב, לחיצה עדינה וערסול מפעילים אותה.$q$,array[$q$החישה העמוקה$q$,$q$חישה עמוקה$q$,$q$מערכת החישה$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$וסטיבולרית$q$,$q$מערכת שיווי המשקל שיושבת באוזן הפנימית. היא מרגישה תנועה, נדנוד וסיבוב, ומתפתחת רק כשמאתגרים אותה בעדינות.$q$,array[$q$המערכת הווסטיבולרית$q$,$q$מערכת שיווי המשקל$q$,$q$הווסטיבולרית$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$כפיפה פיזיולוגית$q$,$q$המנח המכונס שהתינוק הכיר ברחם: גב מעוגל, ברכיים וידיים קרובות לגוף. ערסול שומר עליו, וממנו התינוק יוצא בהדרגה לעולם.$q$,array[$q$הכפיפה הפיזיולוגית$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$קו אמצע$q$,$q$הקו הדמיוני שמחלק את הגוף לימין ושמאל. הבאת ידיים ורגליים לאמצע, ואחר כך חצייה שלו לצד השני, היא הבסיס להתהפכות ולזחילה.$q$,array[$q$קו האמצע$q$,$q$חציית קו האמצע$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$ויסות בשניים$q$,$q$התינוק עדיין לא יודע להירגע לבד. הוא עושה את זה דרכך: המענה שלך לבכי ולאותות שלו הוא מה שמלמד אותו להירגע.$q$,'{}'::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$הנדלינג$q$,$q$איך מרימים, מורידים, מחזיקים ומעבירים את התינוק בין מנחים. הרמה איטית דרך הצד עם תמיכה בראש היא הנדלינג טוב.$q$,'{}'::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$מתו״ק$q$,$q$מגע, תנועה וקול: שלושת הדברים שהתינוק הכיר ברחם ושמרגיעים אותו גם עכשיו. תנועה מהברכיים, מגע יציב בקצב הדופק, וקול עם ויברציה.$q$,array[$q$מתו"ק$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$טרימסטר רביעי$q$,$q$שלושת החודשים הראשונים אחרי הלידה. התינוק נולד עם מערכות שעדיין לא בשלות, וכל מה שמזכיר לו את הרחם עוזר לו לעבור אותם ברוגע.$q$,array[$q$הטרימסטר הרביעי$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$serve and return$q$,$q$התינוק ״מגיש״ (מבט, קול, תנועה) ואת ״מחזירה״. לתת לו לענות ולהיות פעיל בשיחה, ולא רק לדבר אליו.$q$,array[$q$Serve and return$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$דיבור אימהי$q$,$q$הדיבור הטבעי לתינוק: אינטונציה מוגזמת, משפטים קצרים, חזרות, טון גבוה והפסקות. לא ״דיבור תינוקי״ מהיר שבו רק אמא מדברת.$q$,'{}'::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$סימטריה$q$,$q$שני צידי הגוף עובדים באותה מידה: שתי ידיים לאמצע, שתי רגליים לרצפה. הצד והחימום בונים אותה, וממנה יוצאת התהפכות מסודרת.$q$,'{}'::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$דיספלזיה$q$,$q$מצב שבו מפרק הירך לא יושב טוב בשקע שלו. לכן במנשא ובעיטוף הרגליים תמיד חופשיות ומפושקות, בתנוחת M, ואף פעם לא ישרות וצמודות.$q$,array[$q$דיספלזיה של הירך$q$]::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into glossary (term,plain,aliases) values ($q$טונוס$q$,$q$מתח השרירים במנוחה. גם להחזיק וגם להרפות הם חלק מהעבודה: תינוק שלומד להניח את הראש בנינוחות לומד לווסת את הטונוס.$q$,'{}'::text[]) on conflict (term) do update set plain=excluded.plain, aliases=excluded.aliases;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('80472e20-8ee4-434e-b3f6-8c90af1f1fc1',1,$q$מעבר מהרחם לאוויר העולם$q$,$q$<p>שלושת החודשים הראשונים הם <strong>״הטרימסטר הרביעי״</strong>. התינוק נולד עם מערכות שעדיין לא בשלות, וברחם הכל היה קבוע: טמפרטורה, רעשים, חושך, מים, והוא מכונס ומוחזק. ואז הכל השתנה בבת אחת.</p><p>המשימה הראשונה שלו היא לא להתהפך, היא להישאר רגוע וקשוב. את זה הוא עושה דרכך, לא לבד. כל מה שעשינו היום מחזיר לו רגע מהתחושה של הרחם.</p>$q$,$q$<p>רוב העבודה קורית בבית, אבל בלי להגיע לתסכול. מתחילים מדקה ביום.</p>$q$,(select array_agg(id order by ord) from unnest(array['itzuf','lift-lower','side-lying','cradle','matok','relax-pouf']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('80472e20-8ee4-434e-b3f6-8c90af1f1fc1',2,$q$שיפור זמן בטן ותקשורת$q$,null,null,(select array_agg(id order by ord) from unnest(array['communication','why-tummy','why-side','roll-dough','tummy-mirror','tummy-off-mat','relax-pouf']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('80472e20-8ee4-434e-b3f6-8c90af1f1fc1',3,$q$מעבר בין מנחים, שיווי משקל והמערכת הווסטיבולרית$q$,null,null,(select array_agg(id order by ord) from unnest(array['luna-park','belly-on-belly','physio-ball','balance-pouf','relax-tetra']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('80472e20-8ee4-434e-b3f6-8c90af1f1fc1',4,$q$הרפיה והנחת ראש, ידיים לקו האמצע ומיקוד מבט$q$,null,null,(select array_agg(id order by ord) from unnest(array['vision','midline-gaze','head-rest','extra-handling','relax-on-mom']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('80472e20-8ee4-434e-b3f6-8c90af1f1fc1',5,$q$חשיפה למרקמים ומנשא$q$,null,$q$<p><em>האמת היא באמצע, גמישות מחשבתית. לא ללכת בדרך אחת, ולא חייבים לקנות דברים וחומרים: אפשר להשתמש בדברים מהיום־יום ומהטבע.</em></p>$q$,(select array_agg(id order by ord) from unnest(array['textures','carrier','m5-extras','relax-glove']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('3d2b2c93-da57-43e3-966b-de36dda973e7',1,$q$נפלאות גיל 4 חודשים, חציית קו האמצע ומערכת ההצלבה$q$,$q$<p><strong>נפלאות גיל 4 חודשים, וזה לא משבר!</strong> התינוק שהכרנו עד היום פתאום משתנה לחלוטין. נראה שינויים בשינה, בתיאבון ובמצב הרוח. ״יש לי ילד חדש!״</p><p>למה? הוא נפתח יותר לעולם, יוצא מהמנח העוברי, התנועה שלו מאורגנת וחזקה יותר, הוא סקרן ורוצה לחקור, והוא מבין יותר מה קורה סביבו.</p>$q$,null,(select array_agg(id order by ord) from unnest(array['mg-attachment','mg-midline-theory','mg-back-to-tummy','judo-flip','mg-midline-on-back','mg-midline-on-tummy','relax-sounds']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-macha','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('3d2b2c93-da57-43e3-966b-de36dda973e7',2,$q$גילוי כפות הרגליים ועוד$q$,$q$<p>עד גיל 4 חודשים בערך, רוב התינוקות לא ממש מכירים את כפות הרגליים שלהם ולא משתמשים בהן באופן מודע. בשלב ההתהפכויות התינוק כבר מרים את הראש בצורה יציבה, ומתחילה להופיע הפרדת תנועה בין חלקי הגוף, וזה השלב שבו הוא מגלה את כפות הרגליים. הוא מתחיל להניע אותן בצורה מכוונת, עד לתנועה חזקה יותר שגורמת לגוף לנוע ולהתהפך.</p><p>דרכן הוא מתחיל להרגיש שיש משטח שאפשר להישען עליו ולדחוף ממנו. זה בסיס חשוב להמשך: התהפכויות, זחילה ותנועה עצמאית יותר.</p>$q$,null,(select array_agg(id order by ord) from unnest(array['feet-flex','feet-massage','artificial-floor','feet-to-face','scarves-feet','peekaboo','front-cradle-frog','wall-push','mothers-circle','judo-flip','relax-sounds']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-macha','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('3d2b2c93-da57-43e3-966b-de36dda973e7',3,$q$העברת משקל וטכניקות התהפכות מהבטן לגב ומהגב לבטן$q$,$q$<p>עד גיל 6 חודשים לפחות אנחנו מצפות לראות התהפכות בכיוון אחד.</p><p>מערכת שיווי המשקל מתפתחת רק כשאנחנו מאתגרות ומגרות אותה. כשאנחנו מוציאות את התינוק מעט מהאיזון שלו, אנחנו גורמות לו להתחיל <strong>לתכנן את התנועה שלו</strong>. ככה הוא לומד לשלוט בתנועות הגוף כדי לא להתהפך כמו ״בלוק אחד נוקשה״.</p><p>כדי שההיפוך יהיה מאורגן, התינוק צריך ללמוד לייצר הפרדת תנועה בין פלג גוף עליון לתחתון, לבצע העברות משקל צידיות, ולהתארגן מחדש כדי לחזור לקו האמצע. התרגילים היום עוזרים לארגן נכון את השלד והשרירים.</p>$q$,null,(select array_agg(id order by ord) from unnest(array['twist','tummy-elbow','cheek-to-cheek','tetra-balance','tetra-trick','big-clock','relax-hotdog']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-macha','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('3d2b2c93-da57-43e3-966b-de36dda973e7',4,$q$מודעות לכפות הידיים, פעולת הבלימה ושיווי משקל$q$,$q$<p>התנאי לכך שרפלקסים של שיווי משקל והגנה ייכנסו בצורה תקינה למערכת, הוא ש<strong>רפלקס המורו</strong> (רפלקס הבהלה) מתחיל לדעוך.</p><p>לכן היום עבדנו על חוויות מבוקרות ובטוחות של אובדן שיווי משקל ותחושת ״נפילה״, כדי שהמוח ילמד להגיב נכון, יפעיל את רפלקס הבלימה, ויכין את הזרועות להגנה על הגוף.</p>$q$,null,(select array_agg(id order by ord) from unnest(array['hands-massage','artificial-wall','hip-to-mat','arms-on-mom','press-palms','weight-legs','lioness','fall-sim','airplane','relax-sounds']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-macha','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
insert into session_templates (workshop_id,meeting_number,title,intro,outro,exercise_ids,warmup_exercise_ids) values ('3d2b2c93-da57-43e3-966b-de36dda973e7',5,$q$יישור מרפקים, דחיפה על כפות הידיים והכנה לזחילה$q$,$q$<p>סביב גיל 5 עד 6 חודשים אנחנו שואפות לראות מעבר <strong>מהישענות על אמות לדחיפה על כפות הידיים ויישור מרפקים</strong>. זו אחת מאבני הדרך המרכזיות בהכנה לזחילת גחון ובהמשך לזחילה על שש.</p><p>כשהמרפקים מתיישרים ורוב המשקל עובר לכפות הידיים, חגורת הכתפיים מתחזקת, הגב ושרירי הליבה עובדים, והתינוק מתחיל ללמוד לייצב את עצמו ולהרים את בית החזה. זו גם התנועה ההפוכה ממנח האווירון. כאן הוא לומד לנחות אל הקרקע ולבסס יציבות שמכינה אותו לזחילה.</p>$q$,null,(select array_agg(id order by ord) from unnest(array['ball-weight-shift','braking','bubbles','pouf-ride','comm-circle','textures-part','peekaboo-tickles','recap','relax-ball']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug),(select array_agg(id order by ord) from unnest(array['wu-boker','wu-tipuchot','wu-hakpatzot','wu-sivuvim','wu-kapot','wu-kapot-b','wu-alachsonim','wu-macha','wu-nadneda','wu-batzek','wu-batzek-2']::text[]) with ordinality as u(slug,ord) join exercises e on e.slug=u.slug)) on conflict (workshop_id,meeting_number) do update set title=excluded.title, intro=excluded.intro, outro=excluded.outro, exercise_ids=excluded.exercise_ids, warmup_exercise_ids=excluded.warmup_exercise_ids;
